import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract the high_ts watermark value
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events to only those within the watermark
    cdc_events = cdc_events[cdc_events["event_ts"] <= high_ts].copy()

    # Sort events by item_id, then by event_ts, then by event_seq for deterministic ordering
    cdc_events = cdc_events.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ascending=[True, True, True]
    ).reset_index(drop=True)

    # Initialize result as a copy of target_snapshot
    # We'll track item_id -> (qty_on_hand, last_event_ts)
    result_dict = {}
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        result_dict[item_id] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Process each event in order
    for _, event in cdc_events.iterrows():
        item_id = event["item_id"]
        op = event["op"]
        qty = event["qty"]
        event_ts = event["event_ts"]

        if op == "R":  # Receipt: add to quantity
            if item_id not in result_dict:
                # Item not in snapshot, start from 0
                result_dict[item_id] = {
                    "qty_on_hand": 0.0,
                    "last_event_ts": event_ts
                }
            result_dict[item_id]["qty_on_hand"] += qty
            result_dict[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment: set to absolute value
            # Adjustment recreates or updates the item with absolute qty
            result_dict[item_id] = {
                "qty_on_hand": qty,
                "last_event_ts": event_ts
            }

        elif op == "D":  # Delist: remove item from snapshot
            if item_id in result_dict:
                del result_dict[item_id]

    # Convert result back to DataFrame
    if result_dict:
        rows = []
        for item_id, data in result_dict.items():
            rows.append({
                "item_id": item_id,
                "qty_on_hand": data["qty_on_hand"],
                "last_event_ts": data["last_event_ts"]
            })
        new_snapshot = pd.DataFrame(rows)
        # Ensure correct dtypes
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = new_snapshot["last_event_ts"].astype("datetime64[us]")
    else:
        # Empty snapshot
        new_snapshot = pd.DataFrame({
            "item_id": pd.array([], dtype="int64"),
            "qty_on_hand": pd.array([], dtype="float64"),
            "last_event_ts": pd.array([], dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
